// The classification report (ADR-026 Evidence 1, N-A, slice F): counts only, no line of any battle. Every number is an
// integer; shares are parts per million. The report is generated by `fidelity.test.ts` (a subset, in CI) and by
// `node packages/showdown-bridge/test/fidelity/report-cli.ts` (the full run).

import type { WorldWriters } from "../../src/world-writers.ts";
import type { Comparison } from "./oracle.ts";
import type { Candidate, RunData } from "./run.ts";
import type { TurnRecord } from "./evaluate.ts";

/** ADR-026: a writer or id is admitted only with at least this many exercising turns, all equal. */
export const N_EX = 20;

/** The causes a state-difference tag can have. */
export type Cause = "writer" | "information" | "unmodelled" | "engine" | "unclassified";

export interface Blame {
  cause: Cause;
  /** The state item, `volatile:<id>` or `trigger:<id>` the difference is classified against; null for information, unmodelled and unclassified. */
  item: string | null;
  /** For `unmodelled`: the engine id of the state the world lacks. */
  detail?: string;
}

// The names below are this repository's own state-item and tag names (world-writers.ts, oracle.ts), not game rules.
const WRITER_OF_FIELD: Record<string, string> = {
  total_fainted: "total_fainted",
  fainted_last_turn: "fainted_last_turn",
  side_conditions: "condition_duration",
  weather: "condition_duration",
  weather_duration: "condition_duration",
  terrain: "condition_duration",
  terrain_duration: "condition_duration",
  conditions: "condition_duration",
  status_state: "toxic_stage",
  item: "item_removed",
  active_turns: "active_turns",
  last_move: "last_move",
};
const VOLATILE_WRITER: Record<string, string> = { stall: "protect_counter", choicelock: "choice_lock" };

/** Classify one state-difference tag (`own:hp`, `opponent:volatile:mustrecharge`, `field:weather`). */
export function blameOf(tag: string, admitted: ReadonlySet<string>): Blame {
  const parts = tag.split(":");
  const field = parts[1] as string;
  const who = parts[0] as string;
  if (who === "field") return { cause: "writer", item: WRITER_OF_FIELD[field] ?? "condition_duration" };
  if (field === "volatile") {
    const id = parts[2] as string;
    const writer = VOLATILE_WRITER[id];
    if (writer !== undefined) return { cause: "writer", item: writer };
    if (admitted.has(`volatile:${id}`)) return { cause: "writer", item: `volatile:${id}` };
    return { cause: "unmodelled", item: null, detail: id };
  }
  if (field === "hp") return who === "opponent" ? { cause: "information", item: null, detail: "opponent_hp" } : { cause: "engine", item: null, detail: "own_hp" };
  if (field === "pp") return { cause: "information", item: null, detail: who === "opponent" ? "opponent_pp" : "bench_pp" };
  if (field === "status" || field === "status_state") {
    if (field === "status_state") return { cause: "writer", item: "toxic_stage" };
    return { cause: "engine", item: null, detail: `${who}_status` };
  }
  const writer = WRITER_OF_FIELD[field];
  if (writer !== undefined) return { cause: "writer", item: writer };
  return { cause: "engine", item: null, detail: `${who}_${field}` };
}

export interface Stat {
  /** Non-X turns on which the item was present and acted on (the carrier, for an id). */
  exercised: number;
  /** Of those, turns in which the whole comparison was equal. */
  equal: number;
  /** Of those, turns whose difference is classified against the item (or could not be classified at all). */
  blamed: number;
  /** Differing non-X turns in which a difference is classified against the item but the item was absent or nothing acted: the writer wrote nothing where its field differs. */
  missed: number;
}

export interface ItemRow {
  item: string;
  class: string;
  f1: Stat;
  f2: Stat;
  /** At least N_EX exercising turns on both F1 and F2, none blamed. */
  admitted: boolean;
}

export interface Tally {
  turns: number;
  equal: number;
  by_kind: Record<string, number>;
  by_cause: Record<string, number>;
}

/** What a committed report was computed from: a different value means the report is stale and the script must run again. */
export interface Inputs {
  /** `FIDELITY_FORMAT`: the version of the oracle, its arms and its rules. */
  fidelity_format: number;
  showdown_commit: string;
  /** SHA-256 over the names and bytes of every battle file of the corpora. */
  corpora_sha256: string;
  /** SHA-256 of the JCS bytes of the committed writers record with `admitted` emptied (the record the arms start from). */
  base_record_sha256: string;
}

export interface Report {
  inputs: Inputs;
  n_ex: number;
  options: { k: number; m: number };
  corpora: RunData["corpora"];
  decisions: number;
  built: number;
  refusals: Record<string, number>;
  f1: { compared: Tally; x: Tally };
  f2: { compared: Tally; x: Tally };
  /** Pairs of F2 compared (turns times tried pairs). */
  f2_pairs: { compared: number; equal: number; x: number; x_equal: number };
  unmodelled: Record<string, { f1: number; f2: number }>;
  information: Record<string, { f1: number; f2: number }>;
  engine: Record<string, { f1: number; f2: number }>;
  writers: ItemRow[];
  ids: ItemRow[];
  /** The admitted ids (volatile and start-trigger) that pass. */
  admissions: { kind: "volatile" | "start_trigger"; id: string; class: "E" | "W" }[];
}

/**
 * The admission rule: at least N_EX exercising turns in F1 and in F2 that are EQUAL (demonstrated reproductions), and
 * no exercising turn with a difference classified against the item, no difference no state difference names, no missed write.
 * The exercising turns that differ for another classified cause (the opponent's exact hit points, an unmodelled volatile) are
 * counted in `exercised` and reported, but they are neither evidence for the item nor held against it: see the limits in the report.
 */
export const passes = (f1: Stat, f2: Stat): boolean => f1.equal >= N_EX && f2.equal >= N_EX && f1.exercised >= N_EX && f2.exercised >= N_EX && f1.blamed === 0 && f2.blamed === 0 && f1.missed === 0 && f2.missed === 0;

const stat = (): Stat => ({ exercised: 0, equal: 0, blamed: 0, missed: 0 });
const tally = (): Tally => ({ turns: 0, equal: 0, by_kind: {}, by_cause: {} });
const bump = (record: Record<string, number>, key: string): void => void (record[key] = (record[key] ?? 0) + 1);

/** The turn's result in one mode: equal only when every comparison is. The first difference names the kind. */
const merge = (list: readonly Comparison[]): { equal: boolean; kind: string | null; deltas: string[][]; acted: string[][] } => {
  const bad = list.find((c) => !c.equal);
  return { equal: bad === undefined, kind: bad?.kind ?? null, deltas: list.filter((c) => !c.equal).map((c) => c.delta), acted: list.map((c) => c.actors) };
};

/** Causes of the differing comparisons of a turn: per tag blame, or `unclassified` when a difference has no state difference to name. */
function blames(deltas: readonly string[][], admitted: ReadonlySet<string>): Blame[] {
  const out: Blame[] = [];
  for (const delta of deltas) {
    if (delta.length === 0) out.push({ cause: "unclassified", item: null });
    for (const tag of delta) out.push(blameOf(tag, admitted));
  }
  return out;
}

export function buildReport(data: RunData, writers: WorldWriters, inputs: Inputs, candidates: readonly Candidate[] = data.candidates): Report {
  const classOf = new Map(writers.items.map((item) => [item.id as string, item.class as string]));
  const admittedIds = new Set(candidates.map((c) => `${c.kind === "volatile" ? "volatile" : "trigger"}:${c.id}`));
  const report: Report = {
    inputs,
    n_ex: N_EX,
    options: data.options,
    corpora: data.corpora,
    decisions: data.decisions,
    built: data.turns.filter((t) => t.arm === "base").length,
    refusals: data.refusals,
    f1: { compared: tally(), x: tally() },
    f2: { compared: tally(), x: tally() },
    f2_pairs: { compared: 0, equal: 0, x: 0, x_equal: 0 },
    unmodelled: {},
    information: {},
    engine: {},
    writers: [],
    ids: [],
    admissions: [],
  };
  const rows = new Map<string, { f1: Stat; f2: Stat }>();
  const row = (key: string) => rows.get(key) ?? (rows.set(key, { f1: stat(), f2: stat() }), rows.get(key) as { f1: Stat; f2: Stat });

  for (const t of data.turns) {
    const modes: [("f1" | "f2"), Comparison[]][] = [
      ["f1", t.f1 === null ? [] : [t.f1]],
      ["f2", t.f2],
    ];
    for (const [mode, list] of modes) {
      if (list.length === 0) continue;
      const m = merge(list);
      if (t.arm === "base") {
        const bucket = t.x ? report[mode].x : report[mode].compared;
        bucket.turns += 1;
        if (m.equal) bucket.equal += 1;
        else {
          bump(bucket.by_kind, m.kind as string);
          const causes = new Set(blames(m.deltas, admittedIds).map((b) => b.cause));
          for (const cause of causes) bump(bucket.by_cause, cause);
          if (!t.x) {
            for (const b of blames(m.deltas, admittedIds)) {
              const into = b.cause === "unmodelled" ? report.unmodelled : b.cause === "information" ? report.information : b.cause === "engine" ? report.engine : null;
              if (into !== null) (into[b.detail as string] ??= { f1: 0, f2: 0 })[mode] += 1;
            }
          }
        }
        if (!m.equal && !t.x) {
          for (const b of blames(m.deltas, admittedIds)) {
            if (b.cause !== "writer" || b.item === null || b.item.startsWith("volatile:") || b.item.startsWith("trigger:")) continue;
            if (!(t.items.includes(b.item) && m.acted.some((names) => names.length > 0))) row(b.item)[mode].missed += 1;
          }
        }
        if (mode === "f2") {
          report.f2_pairs[t.x ? "x" : "compared"] += list.length;
          report.f2_pairs[t.x ? "x_equal" : "equal"] += list.filter((c) => c.equal).length;
        }
      }
      if (t.x) continue;
      // The exercise count: the item is present and acted on. An id is acted on when its carrier moved or could not (`|move|`, `|cant|`).
      for (const item of t.items) {
        const isId = item.startsWith("volatile:") || item.startsWith("trigger:");
        if (isId !== (t.arm !== "base")) continue;
        if (isId && item !== t.arm) continue;
        const acted = item.startsWith("volatile:") ? m.acted.some((names) => names.some((n) => t.carriers.some((c) => n.endsWith(`: ${c}`)))) : item.startsWith("trigger:") ? true : m.acted.some((names) => names.length > 0);
        if (!acted) continue;
        const s = row(item)[mode];
        s.exercised += 1;
        if (m.equal) s.equal += 1;
        else {
          const found = blames(m.deltas, admittedIds);
          // Blamed when a difference is classified against the item, or when a difference could not be classified at all.
          if (found.some((b) => b.item === item || b.cause === "unclassified")) s.blamed += 1;
        }
      }
    }
  }
  for (const [item, r] of [...rows].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    const entry: ItemRow = { item, class: classOf.get(item) ?? (item.startsWith("volatile:") ? candidates.find((c) => `volatile:${c.id}` === item)?.class ?? "W" : "W"), f1: r.f1, f2: r.f2, admitted: passes(r.f1, r.f2) };
    (item.startsWith("volatile:") || item.startsWith("trigger:") ? report.ids : report.writers).push(entry);
  }
  for (const e of report.ids.filter((e) => e.admitted)) {
    const c = candidates.find((x) => `${x.kind === "volatile" ? "volatile" : "trigger"}:${x.id}` === e.item) as Candidate;
    report.admissions.push({ kind: c.kind, id: c.id, class: c.class });
  }
  report.admissions.sort((a, b) => (a.kind < b.kind ? -1 : a.kind > b.kind ? 1 : a.id < b.id ? -1 : 1));
  return report;
}

const pct = (n: number, d: number): string => (d === 0 ? "n/a" : `${Math.floor((n * 10000) / d) / 100}%`);

export function renderReport(report: Report): string {
  const lines: string[] = [];
  const out = (text = ""): void => void lines.push(text);
  out("# Fork-oracle fidelity report (ADR-026 slice F)");
  out();
  out(`Corpora: ${Object.entries(report.corpora).map(([name, c]) => `${name} ${c.battles} battles / ${c.decisions} own move decisions`).join("; ")}. Decisions ${report.decisions}; worlds built by the committed record ${report.built}; refused ${report.decisions - report.built}.`);
  out(`F2 samples ${report.options.k} own candidates x ${report.options.m} opponent replies per turn (a fixed stride sample of the canonical list). N_ex = ${report.n_ex}.`);
  out();
  out("## Refusals of the committed record (counted, not compared)");
  out();
  out("| code:item | decisions |");
  out("| --- | ---: |");
  for (const [k, v] of Object.entries(report.refusals).sort((a, b) => b[1] - a[1])) out(`| ${k} | ${v} |`);
  out();
  out("## Fidelity, X-class turns apart");
  out();
  out("| mode | compared (non-X) turns | equal | share | X-class turns | X equal | X share |");
  out("| --- | ---: | ---: | ---: | ---: | ---: | ---: |");
  for (const mode of ["f1", "f2"] as const) {
    const r = report[mode];
    out(`| ${mode.toUpperCase()} | ${r.compared.turns} | ${r.compared.equal} | ${pct(r.compared.equal, r.compared.turns)} | ${r.x.turns} | ${r.x.equal} | ${pct(r.x.equal, r.x.turns)} |`);
  }
  out();
  out(`F2 pairs (one pair is one own candidate against one opponent reply): non-X ${report.f2_pairs.equal} of ${report.f2_pairs.compared} equal (${pct(report.f2_pairs.equal, report.f2_pairs.compared)}); X ${report.f2_pairs.x_equal} of ${report.f2_pairs.x}.`);
  out();
  out("## Differences by kind and by cause (non-X turns)");
  out();
  out("A turn can have several causes. `writer`: a state difference classified against an item of the record or an admitted id; `information`: the player cannot know it (the opponent's exact hit points and PP, bench PP); `unmodelled`: engine state the world lacks (a volatile no writer or admitted id covers); `engine`: another field of the pre-turn state; `unclassified`: the turn differs and no pre-turn state difference names it.");
  out();
  out("| mode | outcome | draw_order | request | choice | writer | information | unmodelled | engine | unclassified |");
  out("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
  for (const mode of ["f1", "f2"] as const) {
    const t = report[mode].compared;
    out(`| ${mode.toUpperCase()} | ${["outcome", "draw_order", "request", "choice"].map((k) => t.by_kind[k] ?? 0).join(" | ")} | ${["writer", "information", "unmodelled", "engine", "unclassified"].map((k) => t.by_cause[k] ?? 0).join(" | ")} |`);
  }
  out();
  out("### Unmodelled state behind differing turns");
  out();
  out("| engine id | F1 turns | F2 turns |");
  out("| --- | ---: | ---: |");
  for (const [k, v] of Object.entries(report.unmodelled).sort((a, b) => b[1].f1 + b[1].f2 - a[1].f1 - a[1].f2)) out(`| ${k} | ${v.f1} | ${v.f2} |`);
  out();
  out("### Information-limited state behind differing turns");
  out();
  out("| state | F1 turns | F2 turns |");
  out("| --- | ---: | ---: |");
  for (const [k, v] of Object.entries(report.information).sort()) out(`| ${k} | ${v.f1} | ${v.f2} |`);
  out();
  out("### Other pre-turn state differences behind differing turns (engine)");
  out();
  out("| state | F1 turns | F2 turns |");
  out("| --- | ---: | ---: |");
  for (const [k, v] of Object.entries(report.engine).sort()) out(`| ${k} | ${v.f1} | ${v.f2} |`);
  out();
  const table = (title: string, rows: ItemRow[], note: string): void => {
    out(`## ${title}`);
    out();
    out(note);
    out();
    out("| item | class | F1 exercised | F1 equal | F1 blamed | F1 missed | F2 exercised | F2 equal | F2 blamed | F2 missed | passes |");
    out("| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | --- |");
    for (const r of rows) out(`| ${r.item} | ${r.class} | ${r.f1.exercised} | ${r.f1.equal} | ${r.f1.blamed} | ${r.f1.missed} | ${r.f2.exercised} | ${r.f2.equal} | ${r.f2.blamed} | ${r.f2.missed} | ${r.admitted ? "yes" : "no"} |`);
    out();
  };
  table("Writers of the committed record", report.writers, `An item passes with at least ${report.n_ex} exercising turns in F1 and in F2 that are equal, and no difference classified against it. "Exercised": the item is present in a non-X turn and some Pokemon acted (a \`|move|\` or \`|cant|\` line). "Blamed": a difference is classified against the item or no state difference names it. "Missed": a difference is classified against the item in a turn where the item was absent or nothing acted (the writer wrote nothing where its field differs). The F1 and F2 columns count turns; an item passes with none blamed and none missed.`);
  table("Candidate ids (admitted one at a time into a copy of the record)", report.ids, `"Exercised" for \`volatile:<id>\`: the Pokemon that carries it acted in the turn. For \`trigger:<id>\`: the single admitted id covered a scenario-start restore.`);
  out("## Admissions this report supports");
  out();
  if (report.admissions.length === 0) out("None.");
  for (const a of report.admissions) out(`- ${a.kind} ${a.id} (class ${a.class})`);
  out();
  out("## Limits of the classification");
  out();
  out("- A difference is attributed by the tags of the pre-turn state difference (`stateDelta`), not by a counterfactual run. Fields it does not compare (`slotConditions`, `abilityState`, `itemState`, `lastMoveUsed`, trapping flags, some per-turn fields) cannot be named: a turn that differs because of one of them AND carries an information tag (the opponent's hit points or PP differ in most differing turns) is classified `information`. For that reason an item passes only on its EQUAL exercising turns (at least N_ex of them in F1 and in F2), and the turns that differ for another cause are not evidence for it.");
  out("- \"Exercised\" for a writer means it is present and some Pokemon acted: the writers that are written every turn (`active_turns`, `last_move`, `turn_number`) are exercised in every turn, so their rows say little beyond \"no difference is classified against them\".");
  out("- F2 samples a fixed stride of the canonical candidate list, not a ranked top-k; a turn is one unit however many pairs it has.");
  out("- The committed record is evaluated with `admitted` emptied, over the worlds it builds: refused decisions (the table at the top) are not compared.");
  out();  return lines.join("\n") + "\n";
}

export type { TurnRecord };
